// Normalization logic from FR-2
const raw = $json.body;
let normalized_message = "";
const type = raw.message_type || "text";

switch(type) {
  case "text": normalized_message = raw.message; break;
  case "image": normalized_message = "IMAGEN: " + (raw.metadata.caption || "SIN_CONTEXTO"); break;
  case "audio": normalized_message = "AUDIO_TRANSCRITO: [Simulated Transcription]"; break;
  case "location": normalized_message = `UBICACION: ${raw.metadata.lat}, ${raw.metadata.long}`; break;
  default: normalized_message = "UNKNOWN_FORMAT";
}

return {
  json: {
    input_id: raw.input_id,
    channel: "whatsapp",
    message: normalized_message,
    metadata: raw.metadata
  }
};
